package io.beep.core.adapter.out.postgres;
import static org.assertj.core.api.Assertions.*;
import io.beep.core.app.port.DeveloperRepository.*;
import io.beep.core.domain.link.*;
import io.beep.core.domain.user.*;
import io.beep.core.domain.workspace.Workspace;
import java.time.*;
import java.math.BigDecimal;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.jooq.DSLContext;
import org.jooq.SQLDialect;
import org.jooq.impl.DSL;
import org.junit.jupiter.api.*;
import org.postgresql.ds.PGSimpleDataSource;
import org.testcontainers.containers.PostgreSQLContainer;
class DeveloperIT {
 static DSLContext db;static final Instant NOW=Instant.parse("2026-10-25T12:00:00Z");Workspace ws;Link link;PostgresDeveloperAdapter data;
 @BeforeAll static void setup(){var pg=new PGSimpleDataSource();String url=System.getenv("TEST_DATABASE_URL");if(url==null||url.isBlank()){var c=new PostgreSQLContainer<>("postgres:16-alpine");c.start();url=c.getJdbcUrl();pg.setUser(c.getUsername());pg.setPassword(c.getPassword());}pg.setUrl(url);var f=Flyway.configure().dataSource(pg).cleanDisabled(false).load();f.clean();f.migrate();f.validate();db=DSL.using(pg,SQLDialect.POSTGRES);}
 @BeforeEach void init(){db.execute("TRUNCATE users,slugs CASCADE");var user=User.register(UUID.randomUUID(),new Email("developer@example.com"),"hash","fr",NOW).verifyEmail(NOW);new PostgresUserAdapter(db).insert(user);ws=new PostgresWorkspaceAdapter(db).ensure(Workspace.personal(UUID.randomUUID(),user.id(),"Developer",NOW));db.execute("UPDATE workspaces SET plan_code='elite' WHERE id=?",ws.id());data=new PostgresDeveloperAdapter(db);link=Link.create(UUID.randomUUID(),ws.id(),new Slug("developer"),Destination.parse("https://example.org"),null,NOW);new PostgresLinkAdapter(db).insert(link);}
 Event event(UUID id,String visitor){return new Event(id,ws.id(),"sale",visitor,null,link.id(),new BigDecimal("49.99"),"EUR",null,NOW);}
 @Test void hashedKeysAreScopedAndRevocable(){UUID id=UUID.randomUUID();data.key(new ApiKey(id,ws.id(),"server","sk_prefix","only-a-hash",Set.of("read"),List.of(),false,null,NOW));assertThat(data.keyByHash("only-a-hash")).isPresent();data.revoke(ws.id(),id,NOW);assertThat(data.keyByHash("only-a-hash")).isEmpty();assertThat(data.keys(ws.id()).getFirst().revokedAt()).isEqualTo(NOW);}
 @Test void rateLimitIsSharedAndResetsAtMinuteBoundary(){assertThat(data.rate(ws.id(),"api",2,NOW)).isTrue();assertThat(data.rate(ws.id(),"api",2,NOW)).isTrue();assertThat(data.rate(ws.id(),"api",2,NOW)).isFalse();assertThat(data.rate(ws.id(),"api",2,NOW.plusSeconds(60))).isTrue();}
 @Test void eventIdempotencyDoesNotConsumeQuotaOrDuplicateOutbox(){data.endpoint(new Endpoint(UUID.randomUUID(),ws.id(),"https://example.org/webhook",Set.of("sale"),"cipher",true,NOW));UUID id=UUID.randomUUID();db.transaction(c->{var d=new PostgresDeveloperAdapter(c.dsl());assertThat(d.event(event(id,"visitor"),1)).isTrue();assertThat(d.event(event(id,"visitor"),1)).isFalse();});assertThat(data.deliveries(ws.id())).hasSize(1);assertThatThrownBy(()->db.transaction(c->new PostgresDeveloperAdapter(c.dsl()).event(event(UUID.randomUUID(),"visitor"),1))).hasMessageContaining("quota_exceeded");}
 @Test void attributionAndVisitorDeletionStayWithinWorkspace(){data.touch(ws.id(),"cid",link.id(),null,NOW);data.identify(ws.id(),"cid","visitor");assertThat(data.touches(ws.id(),"visitor",NOW.minusSeconds(1))).hasSize(1);db.transaction(c->new PostgresDeveloperAdapter(c.dsl()).event(event(UUID.randomUUID(),"visitor"),10));data.eraseVisitor(ws.id(),"someone-else");assertThat(data.visitor(ws.id(),"visitor")).hasSize(1);data.eraseVisitor(ws.id(),"visitor");assertThat(data.visitor(ws.id(),"visitor")).isEmpty();assertThat(data.touches(ws.id(),"visitor",NOW.minusSeconds(1))).isEmpty();}
 @Test void deliveryLeasesPreventDoubleClaimAndSupportReplay(){data.endpoint(new Endpoint(UUID.randomUUID(),ws.id(),"https://example.org/webhook",Set.of("sale"),"cipher",true,NOW));db.transaction(c->new PostgresDeveloperAdapter(c.dsl()).event(event(UUID.randomUUID(),"visitor"),10));var first=data.claim(Instant.now().plusSeconds(1),50);assertThat(first).hasSize(1);assertThat(data.claim(Instant.now().plusSeconds(2),50)).isEmpty();var delivery=first.getFirst();data.delivered(delivery.id(),delivery.attempts(),503,NOW,true,NOW);assertThat(data.deliveries(ws.id()).getFirst().status()).isEqualTo("failed");data.replay(ws.id(),delivery.id(),NOW);assertThat(data.deliveries(ws.id()).getFirst().status()).isEqualTo("pending");}
 @Test void deletingResourceDoesNotRefundMonthlyCreations(){new PostgresLinkAdapter(db).delete(link.id());assertThat(new PostgresLinkAdapter(db).countCreatedSince(ws.id(),NOW.minusSeconds(1))).isEqualTo(1);}
 @Test void idempotencyRepliesExpire(){var reply=new Reply("fingerprint",201,"application/json","{\"id\":1}");data.reply(ws.id(),"request-1",reply,NOW);assertThat(data.reply(ws.id(),"request-1",NOW)).contains(reply);assertThat(data.reply(ws.id(),"request-1",NOW.plus(Duration.ofHours(25)))).isEmpty();}
 @Test void utmCampaignsAreStoredAndGroupedByCurrency(){var event=new Event(UUID.randomUUID(),ws.id(),"sale","visitor",null,link.id(),new BigDecimal("49.99"),"EUR",null,NOW,Map.of("source","newsletter","campaign","launch"));db.transaction(c->new PostgresDeveloperAdapter(c.dsl()).event(event,10));assertThat(data.visitor(ws.id(),"visitor").getFirst().utm()).containsEntry("campaign","launch");assertThat((List<?>)data.analytics(ws.id(),NOW.minusSeconds(1)).get("campaigns")).hasSize(1);}
 @Test void bioBadgeFollowsEffectiveRights(){var pages=new PostgresBioPageAdapter(db);var page=io.beep.core.domain.bio.BioPage.create(UUID.randomUUID(),ws.id(),new Slug("bio-developer"),"Developer",NOW);pages.insert(page);var resolver=new PostgresSlugResolverAdapter(db,pages);assertThat(resolver.bioPage(page.id()).orElseThrow().showBadge()).isFalse();db.execute("UPDATE workspaces SET plan_code='starter' WHERE id=?",ws.id());assertThat(resolver.bioPage(page.id()).orElseThrow().showBadge()).isTrue();}
 @Test void anonymousRevenueSurvivesRawRetention(){var old=new Event(UUID.randomUUID(),ws.id(),"sale","visitor",null,link.id(),new BigDecimal("49.99"),"EUR",null,NOW.minus(Duration.ofDays(400)));db.transaction(c->new PostgresDeveloperAdapter(c.dsl()).event(old,10));data.retention(NOW);assertThat(data.visitor(ws.id(),"visitor")).isEmpty();var revenue=(List<?>)data.analytics(ws.id(),NOW.minus(Duration.ofDays(500))).get("revenue");assertThat(revenue).hasSize(1);assertThat(((Map<?,?>)revenue.getFirst()).get("revenue").toString()).startsWith("49.99");}
 @Test void starterRetentionPurgesAnonymousAndRawData(){var old=new Event(UUID.randomUUID(),ws.id(),"sale","visitor",null,link.id(),new BigDecimal("49.99"),"EUR",null,NOW.minus(Duration.ofDays(40)));db.transaction(c->new PostgresDeveloperAdapter(c.dsl()).event(old,10));db.execute("UPDATE workspaces SET plan_code='starter' WHERE id=?",ws.id());data.retention(NOW);assertThat(data.visitor(ws.id(),"visitor")).isEmpty();assertThat((List<?>)data.analytics(ws.id(),NOW.minus(Duration.ofDays(500))).get("revenue")).isEmpty();}
 @Test void dailyVisitorsAreDeduplicatedAndNoIdentifierIsArchived(){for(int i=0;i<2;i++){var event=new Event(UUID.randomUUID(),ws.id(),"pageview","visitor",null,null,BigDecimal.ZERO,null,"https://example.org/page",NOW.plusSeconds(i));db.transaction(c->new PostgresDeveloperAdapter(c.dsl()).event(event,10));}var page=(Map<?,?>)((List<?>)data.analytics(ws.id(),NOW.minusSeconds(1)).get("pages")).getFirst();assertThat(page.get("views").toString()).isEqualTo("2");assertThat(page.get("visitors").toString()).isEqualTo("1");assertThat(db.fetchValue("SELECT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_name='conversion_daily' AND column_name IN ('visitor','cid'))")).isEqualTo(false);}
 @Test void visitorExportIsCompleteBeyondTenThousandEvents(){db.execute("INSERT INTO conversion_events(id,workspace_id,name,visitor,value,at) SELECT gen_random_uuid(),?,'custom:export','visitor',0,?::timestamptz FROM generate_series(1,10001)",ws.id(),NOW.atOffset(ZoneOffset.UTC));assertThat(data.visitor(ws.id(),"visitor")).hasSize(10001);}
 @Test void rawRetentionUsesCalendarMonthsAtMonthEnd(){Instant purgeAt=Instant.parse("2026-03-31T12:00:00Z"),boundary=purgeAt.atZone(ZoneOffset.UTC).minusMonths(13).toInstant();for(var name:List.of("outside","inside")){var e=new Event(UUID.randomUUID(),ws.id(),"pageview",name,null,null,BigDecimal.ZERO,null,"https://example.org",boundary.plusSeconds(name.equals("inside")?1:-1));db.transaction(c->new PostgresDeveloperAdapter(c.dsl()).event(e,10));}data.retention(purgeAt);assertThat(data.visitor(ws.id(),"outside")).isEmpty();assertThat(data.visitor(ws.id(),"inside")).hasSize(1);}
}
